def solve(words, width):
    if not words:
        return []
    res = []
    cur = []
    cur_len = 0  # length of current line without spaces
    for w in words:
        wlen = len(w)
        if not cur:
            # start new line with word (even if longer)
            cur.append(w)
            cur_len = wlen
        else:
            # length if we add space + word
            if cur_len + 1 + wlen <= width:
                cur.append(w)
                cur_len += 1 + wlen
            else:
                # flush current line
                res.append(' '.join(cur))
                # start new line with w
                cur = [w]
                cur_len = wlen
    if cur:
        res.append(' '.join(cur))
    return res

